// The Last Satellite: landing site. three.js scene + station navigation.
// All numbers come from window.SITE_DATA (generated by scripts/build_site_data.py).
import * as THREE from "three";
import { GLTFLoader } from "three/addons/loaders/GLTFLoader.js";
import { DRACOLoader } from "three/addons/loaders/DRACOLoader.js";
import { EffectComposer } from "three/addons/postprocessing/EffectComposer.js";
import { RenderPass } from "three/addons/postprocessing/RenderPass.js";
import { UnrealBloomPass } from "three/addons/postprocessing/UnrealBloomPass.js";
import { OutputPass } from "three/addons/postprocessing/OutputPass.js";
import { ShaderPass } from "three/addons/postprocessing/ShaderPass.js";

const D = window.SITE_DATA || {};
const $ = (s, r = document) => r.querySelector(s);
const $$ = (s, r = document) => [...r.querySelectorAll(s)];
const clamp = (x, a, b) => Math.min(b, Math.max(a, x));
const lerp = (a, b, t) => a + (b - a) * t;
const ease = (t) => (t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2);
const fmtInt = (n) => (n == null ? "—" : Number(n).toLocaleString("en-US"));
const fmt3 = (x) => (x == null ? "—" : Number(x).toFixed(3).replace(/^0/, ""));
const isTouch = matchMedia("(pointer: coarse)").matches;
const SNAP = /[?&]snap/.test(location.search) ? 0.001 : 1; // debug: instant transitions for screenshots
const V = (x, y, z) => new THREE.Vector3(x, y, z);

/* =====================================================================
   RENDERER + FILM PIPELINE
   ===================================================================== */
const canvas = $("#scene");
const renderer = new THREE.WebGLRenderer({ canvas, antialias: true, powerPreference: "high-performance" });
renderer.setClearColor(0x000000, 1);
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.0;
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;

const scene = new THREE.Scene();
const camera = new THREE.PerspectiveCamera(36, 1, 0.1, 4000);

const composer = new EffectComposer(renderer);
composer.addPass(new RenderPass(scene, camera));
const bloom = new UnrealBloomPass(new THREE.Vector2(1, 1), 0.62, 0.85, 0.62); // wide, soft: halation
composer.addPass(bloom);
composer.addPass(new OutputPass());

// The memory look: warm grade, halation tint, gate weave, grain, vignette, a slow light leak.
const film = new ShaderPass({
  uniforms: { tDiffuse: { value: null }, uTime: { value: 0 }, uRes: { value: new THREE.Vector2(1, 1) }, uHeat: { value: 0 }, uGrain: { value: 1 } },
  vertexShader: `varying vec2 vUv; void main(){ vUv=uv; gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.); }`,
  fragmentShader: /* glsl */ `
    uniform sampler2D tDiffuse; uniform float uTime; uniform vec2 uRes; uniform float uHeat; uniform float uGrain; varying vec2 vUv;
    float h(vec2 p){ vec3 p3=fract(vec3(p.xyx)*.1031); p3+=dot(p3,p3.yzx+33.33); return fract((p3.x+p3.y)*p3.z); }
    float vnoise(vec2 p){ vec2 i=floor(p), f=fract(p); f=f*f*(3.-2.*f);
      return mix(mix(h(i),h(i+vec2(1,0)),f.x), mix(h(i+vec2(0,1)),h(i+vec2(1,1)),f.x), f.y); }
    void main(){
      float t = uTime;
      vec2 uv = vUv + vec2(sin(t*1.3)*.00035 + sin(t*5.1)*.0001, cos(t*1.1)*.0004);   // gate weave
      vec2 c = uv - .5; float d = dot(c,c);
      vec2 off = c * d * .006;
      vec3 col = vec3(texture2D(tDiffuse, uv + off).r, texture2D(tDiffuse, uv).g, texture2D(tDiffuse, uv - off).b);

      float lum = dot(col, vec3(.299,.587,.114));
      col += vec3(.10,.035,0.) * smoothstep(.55, 1., lum);                               // halation

      col = pow(col, vec3(.96, 1., 1.08));                                                // warm print grade
      col = mix(col, col * vec3(1.08, .98, .84), .65);
      col = col * .93 + vec3(.032, .021, .012);
      float g = dot(col, vec3(.299,.587,.114));
      col = mix(vec3(g), col, .9);
      col = mix(col, col * vec3(1.2, .82, .6), uHeat * .3);

      float leak = smoothstep(.75, 0., vUv.x) * (.5 + .5*vnoise(vec2(t*.07, vUv.y*1.5)));
      col += vec3(.09, .035, .01) * leak * .55;                                           // light leak

      col *= mix(1., smoothstep(1.05, .25, length(c*vec2(1.05,1.25))), .78);             // vignette

      float fr = floor(t*24.);
      vec2 gp = vUv * uRes / 1.6;
      float n = (h(gp + fr*17.3) + h(gp*1.7 - fr*9.1)) * .5 - .5;
      col += n * uGrain * (.075 + .06*(1.-g));                                            // grain

      float fleck = step(.9993, h(floor(vUv*uRes/3.) + fr*3.7));
      col = mix(col, vec3(.85,.78,.65), fleck*.35*uGrain);                                // dust
      gl_FragColor = vec4(col, 1.);
    }`,
});
composer.addPass(film);

let lofi = false;
function resize() {
  const w = innerWidth, h = innerHeight;
  const dpr = lofi ? 0.6 : Math.min(devicePixelRatio, 1.75);
  renderer.setPixelRatio(dpr);
  renderer.setSize(w, h, false);
  composer.setPixelRatio(dpr);
  composer.setSize(w, h);
  bloom.setSize(w * dpr, h * dpr);
  film.uniforms.uRes.value.set(w, h);
  camera.aspect = w / h;
  camera.fov = w / h < 0.8 ? 56 : w / h < 1.2 ? 44 : 36;
  camera.updateProjectionMatrix();
  scopeResize();
}

/* =====================================================================
   LOADING
   ===================================================================== */
const manager = new THREE.LoadingManager();
manager.onProgress = (_, done, total) => { $("#veilBar").style.width = `${(done / total) * 100}%`; };
const tex = new THREE.TextureLoader(manager);
const maxAniso = renderer.capabilities.getMaxAnisotropy();
function load(url, srgb = true) {
  const t = tex.load(url);
  t.colorSpace = srgb ? THREE.SRGBColorSpace : THREE.NoColorSpace;
  t.anisotropy = maxAniso;
  return t;
}

/* =====================================================================
   LIGHT
   ===================================================================== */
const SUN_DIR = V(-0.82, 0.22, -0.52).normalize();
// the spacecraft gets its own key light from front-left so its wings catch the sun, as in a photograph
const SAT_SUN = V(-0.62, 0.38, 0.68).normalize();
const sunLight = new THREE.DirectionalLight(0xffc89a, 5.4);
sunLight.castShadow = true;
sunLight.shadow.mapSize.set(2048, 2048);
sunLight.shadow.bias = -0.0004;
sunLight.shadow.normalBias = 0.02;
const sc = sunLight.shadow.camera; sc.left = -6; sc.right = 6; sc.top = 6; sc.bottom = -6; sc.near = 1; sc.far = 60;
scene.add(sunLight, sunLight.target);
const earthshine = new THREE.DirectionalLight(0x6d7cff, 0.55);
earthshine.position.set(1, -6, 2);
scene.add(earthshine);
const fill = new THREE.DirectionalLight(0xffd6b0, 0.5);
fill.position.set(2, 3, 10);
scene.add(fill);
scene.add(new THREE.AmbientLight(0x2a1c14, 0.4));
const heatLight = new THREE.PointLight(0xff6a2a, 0, 14, 1.6);
scene.add(heatLight);
{
  const env = new THREE.Scene();
  env.background = new THREE.Color(0x000000);
  const sun = new THREE.Mesh(new THREE.SphereGeometry(5, 16, 16), new THREE.MeshBasicMaterial({ color: new THREE.Color(30, 18, 10) }));
  sun.position.copy(V(-0.62, 0.38, 0.68)).multiplyScalar(40); env.add(sun);
  const planet = new THREE.Mesh(new THREE.SphereGeometry(60, 32, 32), new THREE.MeshBasicMaterial({ color: new THREE.Color(0.12, 0.13, 0.28) }));
  planet.position.set(0, -75, 0); env.add(planet);
  const glow = new THREE.Mesh(new THREE.SphereGeometry(8, 16, 16), new THREE.MeshBasicMaterial({ color: new THREE.Color(1.2, 0.6, 0.35) }));
  glow.position.set(40, 25, -30); env.add(glow);
  scene.environment = new THREE.PMREMGenerator(renderer).fromScene(env, 0.035).texture;
}

/* =====================================================================
   SKY: Tycho star map (NASA) + crisp point stars + a few bright ones
   ===================================================================== */
const sky = new THREE.Mesh(
  new THREE.SphereGeometry(1800, 64, 32),
  new THREE.ShaderMaterial({
    uniforms: { map: { value: load("assets/stars.jpg") } },
    side: THREE.BackSide, depthWrite: false,
    vertexShader: `varying vec2 vUv; void main(){ vUv=uv; gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.); }`,
    fragmentShader: `uniform sampler2D map; varying vec2 vUv;
      void main(){ vec3 c=texture2D(map,vUv).rgb; c=pow(c,vec3(1.35))*.55; c*=vec3(1.08,.96,.86); gl_FragColor=vec4(c,1.); }`,
  })
);
sky.rotation.set(0.55, 2.1, 0.25);
scene.add(sky);

const starUniforms = { uTime: { value: 0 }, uDpr: { value: 1 } };
{
  const N = 6000, pos = new Float32Array(N * 3), col = new Float32Array(N * 3), mag = new Float32Array(N), seed = new Float32Array(N);
  const tints = [new THREE.Color(1, 0.83, 0.68), new THREE.Color(1, 0.94, 0.86), new THREE.Color(0.86, 0.9, 1), new THREE.Color(1, 0.7, 0.5)];
  for (let i = 0; i < N; i++) {
    const u = Math.random() * 2 - 1, t = Math.random() * Math.PI * 2, r = 1500, s = Math.sqrt(1 - u * u);
    pos.set([r * s * Math.cos(t), r * u, r * s * Math.sin(t)], i * 3);
    const c = tints[Math.random() < 0.55 ? 0 : Math.random() < 0.6 ? 1 : Math.random() < 0.6 ? 2 : 3];
    col.set([c.r, c.g, c.b], i * 3);
    mag[i] = Math.pow(Math.random(), 9);
    seed[i] = Math.random() * 100;
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute("position", new THREE.BufferAttribute(pos, 3));
  g.setAttribute("color", new THREE.BufferAttribute(col, 3));
  g.setAttribute("mag", new THREE.BufferAttribute(mag, 1));
  g.setAttribute("seed", new THREE.BufferAttribute(seed, 1));
  const stars = new THREE.Points(g, new THREE.ShaderMaterial({
    uniforms: starUniforms, transparent: true, depthWrite: false, blending: THREE.AdditiveBlending,
    vertexShader: `attribute float mag; attribute float seed; attribute vec3 color; uniform float uTime; uniform float uDpr; varying vec3 vC; varying float vB;
      void main(){ float tw = .82 + .18*sin(uTime*(1.+fract(seed)*3.)+seed*9.);
        vB = (.18 + mag*2.4) * tw; vC=color;
        gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.); gl_PointSize=(1.1 + mag*3.2)*uDpr; }`,
    fragmentShader: `varying vec3 vC; varying float vB; void main(){ float d=length(gl_PointCoord-.5); float a=exp(-d*d*18.); gl_FragColor=vec4(vC*vB, a); }`,
  }));
  stars.frustumCulled = false;
  scene.add(stars);
}

function glareTexture(spike = 0.9, core = 0.05) {
  const c = document.createElement("canvas"); c.width = c.height = 512; const x = c.getContext("2d"), m = 256;
  const g = x.createRadialGradient(m, m, 0, m, m, m);
  g.addColorStop(0, "rgba(255,246,230,1)"); g.addColorStop(core, "rgba(255,206,150,.85)");
  g.addColorStop(core * 3.2, "rgba(255,140,70,.16)"); g.addColorStop(1, "rgba(0,0,0,0)");
  x.fillStyle = g; x.fillRect(0, 0, 512, 512);
  x.globalCompositeOperation = "lighter";
  const s = (len, w, a) => {
    const gr = x.createLinearGradient(m - len, 0, m + len, 0);
    gr.addColorStop(0, "rgba(255,150,80,0)"); gr.addColorStop(0.5, `rgba(255,225,190,${a})`); gr.addColorStop(1, "rgba(255,150,80,0)");
    x.fillStyle = gr; x.fillRect(m - len, m - w / 2, len * 2, w);
  };
  s(256 * spike, 1.6, 0.8); x.save(); x.translate(m, m); x.rotate(Math.PI / 2); x.translate(-m, -m); s(230 * spike, 1.6, 0.7); x.restore();
  const t = new THREE.CanvasTexture(c); t.colorSpace = THREE.SRGBColorSpace; return t;
}
const flares = [];
function addFlare(dir, scale, opacity, texture) {
  const s = new THREE.Sprite(new THREE.SpriteMaterial({ map: texture, blending: THREE.AdditiveBlending, depthWrite: false, transparent: true, opacity }));
  s.position.copy(dir).normalize().multiplyScalar(1400); s.scale.setScalar(scale); s.userData = { base: scale, seed: Math.random() * 10 };
  scene.add(s); flares.push(s); return s;
}
addFlare(V(-0.06, 0.15, -1), 360, 1, glareTexture(1, 0.03));
const smallGlare = glareTexture(0.5, 0.06);
[[0.15, 0.42, -1], [0.75, 0.05, -1], [0.55, -0.2, -0.9], [-0.25, 0.65, -1]].forEach(([x, y, z], i) => addFlare(V(x, y, z), 40 + i * 6, 0.75, smallGlare));

/* =====================================================================
   EARTH (NASA Blue Marble + Black Marble)
   ===================================================================== */
const NOISE = /* glsl */ `
  float hh(vec3 p){ p=fract(p*.3183099+.1); p*=17.; return fract(p.x*p.y*p.z*(p.x+p.y+p.z)); }
  float vn(vec3 x){ vec3 i=floor(x), f=fract(x); f=f*f*(3.-2.*f);
    return mix(mix(mix(hh(i),hh(i+vec3(1,0,0)),f.x),mix(hh(i+vec3(0,1,0)),hh(i+vec3(1,1,0)),f.x),f.y),
               mix(mix(hh(i+vec3(0,0,1)),hh(i+vec3(1,0,1)),f.x),mix(hh(i+vec3(0,1,1)),hh(i+vec3(1,1,1)),f.x),f.y),f.z); }
  float fbm(vec3 p){ float a=.5,s=0.; for(int i=0;i<4;i++){ s+=a*vn(p); p*=2.07; a*=.5; } return s; }
`;
const earthU = {
  uDay: { value: load("assets/earth_day.jpg") },
  uNight: { value: load("assets/earth_lights.jpg", false) },
  uClouds: { value: load("assets/earth_clouds.jpg", false) },
  uSpec: { value: load("assets/earth_spec.jpg", false) },
  uSun: { value: SUN_DIR.clone() },
  uTime: { value: 0 },
};
[earthU.uDay, earthU.uNight, earthU.uClouds, earthU.uSpec].forEach((u) => { u.value.wrapS = THREE.RepeatWrapping; });
const EARTH_R = 60;
const earth = new THREE.Mesh(
  new THREE.SphereGeometry(EARTH_R, 256, 128),
  new THREE.ShaderMaterial({
    uniforms: earthU,
    vertexShader: `varying vec2 vUv; varying vec3 vN; varying vec3 vW; varying vec3 vObj;
      void main(){ vUv=uv; vObj=position; vN=normalize(mat3(modelMatrix)*normal); vec4 w=modelMatrix*vec4(position,1.); vW=w.xyz; gl_Position=projectionMatrix*viewMatrix*w; }`,
    fragmentShader: NOISE + /* glsl */ `
      uniform sampler2D uDay, uNight, uClouds, uSpec; uniform vec3 uSun; uniform float uTime;
      varying vec2 vUv; varying vec3 vN; varying vec3 vW; varying vec3 vObj;
      void main(){
        vec3 N = normalize(vN), V = normalize(cameraPosition - vW), L = normalize(uSun);
        float ndl = dot(N, L);
        vec2 cuv = vUv + vec2(uTime * .0004, 0.);
        float cl = texture2D(uClouds, cuv).r;
        cl *= .78 + .44 * fbm(vObj * 1.6 + uTime*.02);
        cl = smoothstep(.08, .95, cl);
        float shadow = texture2D(uClouds, cuv + vec2(-.0015, .0008)).r;
        vec3 day = texture2D(uDay, vUv).rgb * (1. - shadow * .45);
        float spec = texture2D(uSpec, vUv).r;
        float light = smoothstep(-.08, .45, ndl);
        vec3 sunTint = mix(vec3(1., .42, .16), vec3(1., .93, .85), smoothstep(.0, .45, ndl));
        vec3 surf = mix(day, vec3(1.), cl) * sunTint * light * 1.5;
        vec3 H = normalize(L + V);
        surf += vec3(1., .72, .45) * pow(max(dot(N, H), 0.), 60.) * spec * (1. - cl) * light * 1.4;
        float night = texture2D(uNight, vUv).r;
        surf += vec3(1., .62, .3) * pow(night, 1.6) * smoothstep(.12, -.18, ndl) * (1. - cl * .9) * 1.6;
        float nv = max(dot(N, V), 0.);
        float fres = pow(1. - nv, 3.);
        vec3 atm = mix(vec3(1., .5, .25), vec3(.35, .55, 1.), smoothstep(-.05, .5, ndl));
        surf = mix(surf, atm * (.12 + light * .9), fres * .8 * smoothstep(-.35, .15, ndl));
        gl_FragColor = vec4(surf, 1.);
      }`,
  })
);
earth.rotation.set(0.25, -1.6, 0.42);
earth.userData = { tag: "Last words · re-entry", go: "transmission" };
scene.add(earth);
const atmosphere = new THREE.Mesh(
  new THREE.SphereGeometry(EARTH_R * 1.025, 160, 80),
  new THREE.ShaderMaterial({
    uniforms: earthU, side: THREE.BackSide, transparent: true, blending: THREE.AdditiveBlending, depthWrite: false,
    vertexShader: `varying vec3 vN; varying vec3 vW; void main(){ vN=normalize(mat3(modelMatrix)*normal); vec4 w=modelMatrix*vec4(position,1.); vW=w.xyz; gl_Position=projectionMatrix*viewMatrix*w; }`,
    fragmentShader: `uniform vec3 uSun; varying vec3 vN; varying vec3 vW;
      void main(){ vec3 V=normalize(cameraPosition-vW); vec3 N=normalize(vN);
        float rim = clamp(1. - abs(dot(V, N)), 0., 1.);
        float glow = pow(rim, 6.) * 1.6;
        float lit = smoothstep(-.4, .5, dot(-N, uSun));
        vec3 c = mix(vec3(1., .48, .22), vec3(.38, .58, 1.), lit);
        gl_FragColor = vec4(c * glow * (.25 + lit), glow); }`,
  })
);
scene.add(atmosphere);
function placeEarth(p) { earth.position.copy(p); atmosphere.position.copy(p); }
placeEarth(V(-22, -EARTH_R - 11, -30));

/* =====================================================================
   SATURN (NASA texture, real ring profile, mutual shadows)
   ===================================================================== */
const SAT_R = 30;
const planetGroup = new THREE.Group();
planetGroup.position.set(330, 40, -620);
scene.add(planetGroup);
const ringTilt = new THREE.Euler(-1.22, -0.25, 0.42);
const ringNormal = V(0, 0, 1).applyEuler(ringTilt);
const saturnU = { uMap: { value: load("assets/saturn.jpg") }, uSun: { value: SUN_DIR.clone() }, uRingN: { value: ringNormal }, uR: { value: SAT_R } };
const saturn = new THREE.Mesh(
  new THREE.SphereGeometry(SAT_R, 128, 64),
  new THREE.ShaderMaterial({
    uniforms: saturnU,
    vertexShader: `varying vec2 vUv; varying vec3 vN; varying vec3 vL; void main(){ vUv=uv; vN=normalize(mat3(modelMatrix)*normal); vL=mat3(modelMatrix)*position; gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.); }`,
    fragmentShader: `uniform sampler2D uMap; uniform vec3 uSun, uRingN; uniform float uR; varying vec2 vUv; varying vec3 vN; varying vec3 vL;
      float ringDensity(float r){ r/=uR;
        return smoothstep(1.24,1.3,r)*(1.-smoothstep(1.52,1.53,r))*.25 + smoothstep(1.53,1.56,r)*(1.-smoothstep(1.94,1.95,r))*.95
             + smoothstep(2.03,2.05,r)*(1.-smoothstep(2.26,2.27,r))*.7; }
      void main(){ vec3 N=normalize(vN), L=normalize(uSun); float ndl=dot(N,L);
        vec3 c = texture2D(uMap, vUv).rgb;
        float lit = smoothstep(-.05,.35,ndl);
        float t = -dot(vL, uRingN) / dot(L, uRingN); float sh = 0.;
        if (t > 0.) sh = ringDensity(length(vL + L*t));
        float gy = dot(c, vec3(.3,.59,.11)); c = mix(vec3(gy), c, .45);            // the NASA map is oversaturated
        c = pow(c, vec3(1.1)) * vec3(1.,.9,.78);
        c *= lit * (1. - sh*.7) * .72;
        c += vec3(.02,.012,.01) * (1.-lit);
        gl_FragColor = vec4(c, 1.); }`,
  })
);
saturn.userData = { tag: "Model laboratory", go: "lab" };
planetGroup.add(saturn);
const ring = new THREE.Mesh(
  new THREE.RingGeometry(SAT_R * 1.22, SAT_R * 2.36, 512, 1),
  new THREE.ShaderMaterial({
    uniforms: saturnU, side: THREE.DoubleSide, transparent: true, depthWrite: false,
    vertexShader: `varying vec3 vP; varying vec3 vW; void main(){ vP=position; vW=mat3(modelMatrix)*position; gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.); }`,
    fragmentShader: NOISE + `uniform vec3 uSun, uRingN; uniform float uR; varying vec3 vP; varying vec3 vW;
      void main(){ float r = length(vP.xy)/uR;
        float k = vn(vec3(r*90.,0.,0.))*.5 + vn(vec3(r*420.,3.,0.))*.3 + vn(vec3(r*1300.,7.,0.))*.2;   // ringlets
        float C = smoothstep(1.24,1.3,r)*(1.-smoothstep(1.52,1.53,r)) * (.08 + .16*k);
        float B = smoothstep(1.53,1.56,r)*(1.-smoothstep(1.94,1.95,r)) * (.35 + .6*k);
        float A = smoothstep(2.03,2.05,r)*(1.-smoothstep(2.26,2.27,r)) * (.25 + .45*k);
        A *= 1. - (smoothstep(2.205,2.21,r)*(1.-smoothstep(2.215,2.22,r)))*.9;
        float F = exp(-pow((r-2.33)*160.,2.)) * .35;
        float a = clamp(C + B + A + F, 0., 1.);
        vec3 col = mix(vec3(.55,.45,.36), vec3(.95,.84,.68), smoothstep(1.5,2.,r));
        col = mix(col, vec3(.7,.6,.5), C*1.5);
        vec3 L = normalize(uSun); float b = dot(vW, L); float d2 = dot(vW,vW) - b*b;
        float inShadow = (b < 0. && d2 < uR*uR) ? 1. : 0.;
        float light = .3 + .7 * abs(dot(L, uRingN));
        col *= light * (1. - inShadow*.85) * .7;
        gl_FragColor = vec4(col, a * .85); }`,
  })
);
ring.rotation.copy(ringTilt);
ring.userData = saturn.userData;
planetGroup.add(ring);

/* =====================================================================
   THE SPACECRAFT (NASA 3D Resources, public domain)
   ===================================================================== */
const satRig = new THREE.Group();
const sat = new THREE.Group();
satRig.add(sat);
scene.add(satRig);
const SAT_HOME = V(2.1, 1.3, 0);
satRig.position.copy(SAT_HOME);
const hoverables = [earth, saturn, ring];
const heatMats = [];
const gltfLoader = new GLTFLoader(manager);
gltfLoader.setDRACOLoader(new DRACOLoader().setDecoderPath("https://cdn.jsdelivr.net/npm/three@0.160.0/examples/jsm/libs/draco/gltf/"));
gltfLoader.load("assets/mro.glb", (gltf) => {
  const m = gltf.scene;
  const box = new THREE.Box3().setFromObject(m), size = box.getSize(V(0, 0, 0)), ctr = box.getCenter(V(0, 0, 0));
  m.position.sub(ctr);
  const wrap = new THREE.Group(); wrap.add(m); wrap.scale.setScalar(7.4 / Math.max(size.x, size.y, size.z));
  wrap.rotation.set(0, Math.PI / 2, 0);
  sat.add(wrap);
  if (SNAP < 1) window.__dbg = { sat, wrap, satRig, planetGroup, earth, placeEarth, V };
  m.traverse((o) => {
    if (!o.isMesh) return;
    o.castShadow = true; o.receiveShadow = true;
    const mats = Array.isArray(o.material) ? o.material : [o.material];
    mats.forEach((mat) => {
      const n = (mat.name || "").toLowerCase();
      mat.envMapIntensity = 1.2;
      if (n.includes("foil")) { mat.metalness = 0.92; mat.roughness = 0.38; mat.emissive = new THREE.Color(0xff5a1f); mat.emissiveIntensity = 0; heatMats.push(mat); }
      else if (n.includes("solar")) { mat.metalness = 0.75; mat.roughness = 0.2; mat.envMapIntensity = 2; }
      else { mat.roughness = Math.max(0.55, mat.roughness ?? 0.6); mat.metalness = Math.min(0.25, mat.metalness ?? 0); mat.color?.multiplyScalar(0.72); mat.envMapIntensity = 0.7; }
      if (mat.map) mat.map.anisotropy = maxAniso;
    });
    const n = mats.map((x) => (x.name || "").toLowerCase()).join(" ");
    o.userData = n.includes("solar") ? { tag: "Solar wings · the engine", go: "engine" }
      : n.includes("default") || n.includes("cover") || n.includes("tower") ? { tag: "High-gain dish · mission log", go: "memory" }
      : { tag: "Spacecraft bus · signal observatory", go: "signal" };
    hoverables.push(o);
  });
});
sat.rotation.set(0.18, -0.35, 0.06);

/* =====================================================================
   STATIONS (camera choreography)
   ===================================================================== */
const STATIONS = {
  intro:        { cam: V(-6, 7, 62),      look: V(6, -1, -30) },
  orbit:        { cam: V(-1.2, 2.4, 21),  look: V(0.2, -0.4, 0) },
  signal:       { cam: V(-2.6, 2.4, 14),  look: V(7.4, 0.6, 0),    panel: "#panel-signal" },
  engine:       { cam: V(-7.5, 5, 9),     look: V(7, 0.2, -1.5), panel: "#panel-engine" },
  memory:       { cam: V(7.6, 3.2, 10.5), look: V(5.4, 0.9, -1.5), panel: "#panel-memory" },
  lab:          { cam: V(-4, 3, 14),      look: V(170, 60, -420),  panel: "#panel-lab" },
  transmission: { cam: V(-3, 6, 24),      look: V(-1, -3.6, -14),  panel: "#finale", heat: 1 },
};
const PORTRAIT = { orbit: { cam: V(1.6, 2.6, 30), look: V(2.1, -4.2, 0) }, transmission: { cam: V(0, 7, 32), look: V(1, -4, -14), heat: 1 } };
const stationFor = (name) => (innerWidth / innerHeight < 0.9 && PORTRAIT[name]) || STATIONS[name];
const ORDER = ["orbit", "signal", "engine", "memory", "lab", "transmission"];
const camPos = STATIONS.intro.cam.clone(), camLook = STATIONS.intro.look.clone();
let tween = null, current = "intro";
const mouse = new THREE.Vector2(), mouseS = new THREE.Vector2();
let heat = 0, heatTarget = 0;

function flyTo(name, dur = 2.4) {
  const s = stationFor(name);
  tween = { t0: performance.now(), dur: dur * 1000 * SNAP, fromP: camPos.clone(), fromL: camLook.clone(), toP: s.cam.clone(), toL: s.look.clone() };
  heatTarget = s.heat || 0;
  if (SNAP < 1) { camPos.copy(s.cam); camLook.copy(s.look); tween = null; }
}
function tick(now) {
  if (tween) {
    const t = clamp((now - tween.t0) / tween.dur, 0, 1), e = ease(t);
    camPos.lerpVectors(tween.fromP, tween.toP, e);
    camPos.y += Math.sin(Math.PI * e) * 0.9 * tween.fromP.distanceTo(tween.toP) / 20;
    camLook.lerpVectors(tween.fromL, tween.toL, e);
    if (t >= 1) tween = null;
  }
  mouseS.lerp(mouse, 0.035);
  const par = current === "orbit" ? 0.5 : 0.2;
  camera.position.set(camPos.x + mouseS.x * par, camPos.y + mouseS.y * par * 0.6, camPos.z);
  camera.lookAt(camLook);
}

/* =====================================================================
   SOUND (synthesised; off until the visitor turns it on)
   ===================================================================== */
const Sound = (() => {
  let ctx, master, on = false, started = false;
  function start() {
    if (started) return; started = true;
    ctx = new (window.AudioContext || window.webkitAudioContext)();
    master = ctx.createGain(); master.gain.value = 0; master.connect(ctx.destination);
    const lp = ctx.createBiquadFilter(); lp.type = "lowpass"; lp.frequency.value = 420; lp.Q.value = 3; lp.connect(master);
    [55, 82.41, 110.3].forEach((f, i) => { const o = ctx.createOscillator(); o.type = i === 1 ? "triangle" : "sine"; o.frequency.value = f; o.detune.value = (i - 1) * 6; const g = ctx.createGain(); g.gain.value = [0.09, 0.05, 0.03][i]; o.connect(g).connect(lp); o.start(); });
    const lfo = ctx.createOscillator(); lfo.frequency.value = 0.05; const lg = ctx.createGain(); lg.gain.value = 260; lfo.connect(lg).connect(lp.frequency); lfo.start();
    const buf = ctx.createBuffer(1, ctx.sampleRate * 2, ctx.sampleRate); const d = buf.getChannelData(0);
    for (let i = 0; i < d.length; i++) d[i] = (Math.random() * 2 - 1) * (Math.random() < 0.002 ? 4 : 1);
    const n = ctx.createBufferSource(); n.buffer = buf; n.loop = true;
    const bp = ctx.createBiquadFilter(); bp.type = "bandpass"; bp.frequency.value = 2200; bp.Q.value = 0.7;
    const ng = ctx.createGain(); ng.gain.value = 0.01; n.connect(bp).connect(ng).connect(master); n.start();
    beacon();
  }
  function set(v) { on = v; if (v) start(); if (master) { ctx.resume(); master.gain.setTargetAtTime(on ? 0.9 : 0, ctx.currentTime, 0.4); } }
  function tone(f, dur, type = "sine", vol = 0.05, f2) {
    if (!ctx || !on) return;
    const o = ctx.createOscillator(), g = ctx.createGain(), t = ctx.currentTime;
    o.type = type; o.frequency.setValueAtTime(f, t); if (f2) o.frequency.exponentialRampToValueAtTime(f2, t + dur);
    g.gain.setValueAtTime(0, t); g.gain.linearRampToValueAtTime(vol, t + 0.008); g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    o.connect(g).connect(master); o.start(t); o.stop(t + dur + 0.05);
  }
  function whoosh(dur = 1.4) {
    if (!ctx || !on) return;
    const t = ctx.currentTime, b = ctx.createBuffer(1, ctx.sampleRate * dur, ctx.sampleRate), d = b.getChannelData(0);
    for (let i = 0; i < d.length; i++) d[i] = Math.random() * 2 - 1;
    const s = ctx.createBufferSource(); s.buffer = b; const f = ctx.createBiquadFilter(); f.type = "bandpass"; f.Q.value = 1.2;
    f.frequency.setValueAtTime(200, t); f.frequency.exponentialRampToValueAtTime(1800, t + dur * 0.45); f.frequency.exponentialRampToValueAtTime(260, t + dur);
    const g = ctx.createGain(); g.gain.setValueAtTime(0, t); g.gain.linearRampToValueAtTime(0.08, t + dur * 0.4); g.gain.linearRampToValueAtTime(0, t + dur);
    s.connect(f).connect(g).connect(master); s.start(t);
  }
  function beacon() {
    const code = "--- .--. ...", u = 0.085; let t = 0;
    for (const ch of code) { if (ch === " ") { t += u * 3; continue; } const d = ch === "-" ? u * 3 : u; setTimeout(() => tone(740, d, "sine", 0.022), t * 1000); t += d + u; }
    setTimeout(beacon, 9000 + Math.random() * 7000);
  }
  return { set, get on() { return on; }, blip: () => tone(1320, 0.05, "square", 0.01), click: () => tone(520, 0.18, "triangle", 0.045, 180), whoosh, tone };
})();

