/* =====================================================================
   SIGNAL OBSERVATORY
   ===================================================================== */
const scope = $("#scope"), sx = scope.getContext("2d");
const traces = D.traces || [];
let traceIdx = 0, sweep = 0, revealed = false;
const TH = D.thresholds || { high: 0.8, low: 0.05 };
const decision = (p) => (p >= TH.high ? "PRIORITISE" : p >= TH.low ? "QUEUE" : "ARCHIVE");
function scopeResize() {
  const r = scope.getBoundingClientRect(), dpr = Math.min(devicePixelRatio, 2);
  scope.width = Math.max(1, r.width * dpr); scope.height = Math.max(1, r.height * dpr);
}
function zeroRuns(v) {
  const runs = []; let s = -1;
  v.forEach((x, i) => { if (x === 0) { if (s < 0) s = i; } else if (s >= 0) { if (i - s >= 2) runs.push([s, i - 1]); s = -1; } });
  if (s >= 0 && v.length - s >= 2) runs.push([s, v.length - 1]);
  return runs;
}
$("#scopeTapes").innerHTML = traces.map((t, i) => `<button type="button" data-i="${i}">Segment ${t.segment_id}<small>${t.channel} · ${t.kind}</small></button>`).join("");
$("#scopeTapes").addEventListener("click", (e) => { const b = e.target.closest("button"); if (b) selectTrace(+b.dataset.i); });
function selectTrace(i) {
  if (!traces.length) return;
  traceIdx = clamp(i, 0, traces.length - 1); sweep = SNAP < 1 ? 1 : 0; revealed = false;
  $$("#scopeTapes button").forEach((b, k) => b.classList.toggle("on", k === traceIdx));
  const t = traces[traceIdx];
  $("#scopeCh").textContent = `${t.channel} · ${t.channel_name}`;
  $("#scopeMeta").textContent = `recorded ${t.start.slice(0, 10)}, ${t.start.slice(11, 16)} UTC`;
  $("#revealBtn").textContent = "Reveal ground truth";
  renderVerdict(); Sound.click();
}
function renderVerdict() {
  const t = traces[traceIdx]; if (!t) return;
  $("#scopeVerdict").innerHTML =
    `<span>P(ANOMALY) <span class="hot">${t.probability.toFixed(3)}</span> → <span class="hot">${decision(t.probability)}</span></span>` +
    (revealed ? `<span class="truth">TRUTH: ${t.label ? "ANOMALY" : "NOMINAL"} · ${t.case}${t.case === "FN" ? " (MISSED)" : ""}</span>` : `<span>TRUTH: SEALED</span>`);
}
$("#revealBtn").addEventListener("click", () => {
  revealed = !revealed; renderVerdict(); Sound.tone(revealed ? 440 : 330, 0.4, "triangle", 0.05, revealed ? 880 : 160);
  $("#revealBtn").textContent = revealed ? "Seal again" : "Reveal ground truth";
});
function drawScope(dt) {
  const W = scope.width, H = scope.height; if (!W || !traces.length) return;
  const v = traces[traceIdx].v, n = v.length;
  sweep = Math.min(1, sweep + dt * 0.5);
  sx.clearRect(0, 0, W, H);
  sx.strokeStyle = "rgba(140,196,202,.10)"; sx.lineWidth = 1;
  for (let i = 1; i < 10; i++) { const x = (W * i) / 10; sx.beginPath(); sx.moveTo(x, 0); sx.lineTo(x, H); sx.stroke(); }
  for (let j = 1; j < 6; j++) { const y = (H * j) / 6; sx.beginPath(); sx.moveTo(0, y); sx.lineTo(W, y); sx.stroke(); }
  let lo = Infinity, hi = -Infinity; for (const x of v) { if (x < lo) lo = x; if (x > hi) hi = x; }
  const pad = (hi - lo) * 0.18 || 1, top = H * 0.17, bot = H * 0.8;
  const X = (i) => (i / (n - 1)) * W, Y = (x) => bot - ((x - lo + pad) / (hi - lo + 2 * pad)) * (bot - top);
  sx.fillStyle = "rgba(194,90,46,.34)";
  zeroRuns(v).forEach(([a, b]) => { if (a / n < sweep) sx.fillRect(X(a), top - 10, Math.max(2, X(Math.min(b, n * sweep)) - X(a)), bot - top + 20); });
  const upto = Math.floor(sweep * (n - 1));
  sx.lineJoin = "round";
  for (const [w, a] of [[7, 0.08], [3.5, 0.22], [1.6, 1]]) {
    sx.strokeStyle = `rgba(170,236,240,${a})`; sx.lineWidth = w * (W / 900);
    sx.beginPath(); for (let i = 0; i <= upto; i++) i ? sx.lineTo(X(i), Y(v[i])) : sx.moveTo(X(i), Y(v[i])); sx.stroke();
  }
  $("#scopeState").textContent = sweep < 1 ? "▶ PLAY" : "■ END";
}

